# area: inheritance_mro
# hypothesis: In a diamond MRO with cooperative super() calls, the @override greet in Bottom is compatible and the chain returns 111, while the str-returning override in Clash is an LSP error that checkers may report on different lines.
from typing import override, reveal_type


class Base:
    def greet(self, n: int) -> int:
        return n


class Left(Base):
    def greet(self, n: int) -> int:
        return super().greet(n) + 1


class Right(Base):
    def greet(self, n: int) -> int:
        return super().greet(n) * 10


class Bottom(Left, Right):
    @override
    def greet(self, n: int) -> int:
        return super().greet(n) + 100


class Clash(Left):
    @override
    def greet(self, n: int) -> str:  # expect-error: return type str is incompatible with int
        return str(n)


b = Bottom()
reveal_type(b.greet(1))
print(b.greet(1))
print([k.__name__ for k in Bottom.__mro__])
print(Clash().greet(2))
